      "authored_text": "good things don't last, but bad things don't last too. yes?\n\n...\n\ntheoretically.\n\nwhat's not temporary? infinity? infinity is subject to its own law, and doesn't work without it.\n\nthis sentence is false; nothing matters.\n\npicture nothing--you can't.\n\n...unless i lack the imagination to picture nothing, but it's difficult to imagine that nothing can be imagined.\n\n???\n\n???\n\n???\n\ntruestory.xml",
