      "audio_url": "audio/bd698e8d6771de37c382e8aab61e666d81ccdbd46d83d707fe4359aab2c363c6.mp3",
      "authored_text": "hi nopony, \n\ni'm sure you're not seeing this, so i've gone ahead and greenlit myself.\nbasically, i may only have a few more years on me, which is a generous approximation already.\ni've been adviced on several occasions to talk to somepony--anypony--so here i am talking to nopony instead muehhehheh. somehow, it feels like talking to somepony though, just because it's online, but nopony is going to see this, so i've gone ahead and greenlit myself, my friend. 👍️\n\nfeel free to not leave a comment because there is no comment section, or you can email me @.\n\nwell, felt good to get some stuff off my chest.\n\nmay life not weigh on you, rather lift you up, friend, nopony.\n\n-doc",
      "content_hash": "db5ff03b9c5459150ad0117f08133e9b1347107e5014c90159a0d97ed4a43a65",
