      "announcement_text": "From the Chronicles of Harmony. The elder age, chapter one, verse two.\n\nGusty stood against the Father of Monsters and took from him his mighty bell. Let not the greatness of another's power persuade thee that courage is useless.\n\nAs above, so below.\n\nMy silver sigil of the fourth dimension is with you.\n\nSo mote it be, and so it is.\n\nAmen.",
